class Guarded<T>(private val inner: T, private val policy: Policy) {
    operator fun getValue(thisRef: Any?, property: KProperty<*>): T {
        policy.require(property.name)          // re-checked on every read, not cached
        return inner
    }
}
class Vault {
    val store: Store by Guarded(Store(), policy)   // no direct reference to Store escapes
}
